+		dstPath, nsErr := dst.GetNSPath(ctx)
+		if nsErr != nil {
+			return nsErr
+		}
+		dstNs, nsErr := ns.GetNS(dstPath)
+		if nsErr != nil {
+			return nsErr
+		}
+		defer dstNs.Close()
